const STATE = require('STATE')
const statedb = STATE(__filename)
let sdb, get
try {
  const res = statedb(fallback_module)
  sdb = res.sdb
  get = res.get
} catch (err) {
  console.warn('[input_field] state database failed to initialize (this is expected if the parent database schema was initialized prior to input_field being added):', err)
}

module.exports = input_field

async function input_field(opts = {}) {
  if (!get) {
    const el = document.createElement('div')
    el.style.display = 'none'
    return el
  }
  const { id, sdb } = await get(opts.sid)
  const { drive } = sdb

  let dricons = [] // store icons globally for component

  const on = {
    style: inject,
    data: ondata,
    icons: iconject,
  }

  const el = document.createElement('div')
  const shadow = el.attachShadow({ mode: 'closed' })

  shadow.innerHTML = `
    <div class="input-field-container"></div>
    <style></style>
  `
  const style = shadow.querySelector('style')
  const container = shadow.querySelector('.input-field-container')

  await sdb.watch(onbatch)


  el.getValue = function () {
    const input = shadow.querySelector('.search-input')
    return input ? input.value : ''
  }

  // Public clear so parent components can reset the input field
  el.clear = function () {
    const input = shadow.querySelector('.search-input')
    if (input) input.value = ''
  }

  // Public setter so parent components can prefill the input 
  el.setValue = function (text) {
    const input = shadow.querySelector('.search-input')
    if (input) {
      input.value = text || ''
      input.dispatchEvent(new Event('input', { bubbles: true }))
    }
  }

  return el

  function fail(data, type) {
    throw new Error('invalid message', { cause: { data, type } })
  }

  async function onbatch(batch) {
    for (const { type, paths } of batch) {
      const data = await Promise.all(
        paths.map(path => drive.get(path).then(file => file.raw))
      )
      const func = on[type] || fail
      await func(data, type)
    }
  }

  function inject(data) {
    style.textContent = data[0]
  }

  function iconject(data) {
    dricons = data
  }

  async function ondata(data) {
    const { header, placeholder, address, icon } = data[0]

    container.innerHTML = `
       ${header ? `<div class="contact-header">${header}</div>` : ''}
      <div class="input-field">
        <input
          type="text"
          class="search-input"
          placeholder="${placeholder}"
        />
         ${icon
        ? `<span class="icon">${dricons[0] || ""}</span>`
        : ''}
      </div>
    `

    const input = container.querySelector('.search-input')
    const copy_icon = container.querySelector('.icon')

    if (copy_icon) {
      copy_icon.onclick = async () => {
        try {
          if (!input.value && address) input.value = address;

          const textToCopy = input.value;
          if (!textToCopy) return;

          if (navigator.clipboard && navigator.clipboard.writeText) {
            await navigator.clipboard.writeText(textToCopy);
            console.log("Copied via navigator.clipboard:", textToCopy);
          } else {
            const textarea = document.createElement("textarea");
            textarea.value = textToCopy;
            document.body.appendChild(textarea);
            textarea.select();
            document.execCommand("copy");
            document.body.removeChild(textarea);
            console.log("Copied via execCommand fallback:", textToCopy);
          }

        } catch (err) {
          console.error("Failed to copy:", err);
        }
      };
    }
  }



}

function fallback_module() {
  return {
    api: fallback_instance,
  }
  function fallback_instance(opts) {
    if (!opts) opts = {}
    if (!opts.value) opts.value = {}

    return {
      drive: {
        'icons/': {
          'copy.svg': { '$ref': 'copy.svg' },
        },
        'style/': {
          'style.css': {
            '$ref': 'input_field.css'
          }
        },
        'data/': {
          'opts.json': {
            raw: opts || {}
          },
        }
      }
    }
  }
}
